package com.acrenex.app.activities;
import android.database.Cursor;import android.os.Bundle;import android.widget.LinearLayout;import androidx.appcompat.app.AppCompatActivity;import com.acrenex.app.ai.ChangeDetectionManager;import com.acrenex.app.database.DatabaseManager;import com.acrenex.app.utils;import com.google.android.material.button.MaterialButton;
public class ChangeDetectionActivity extends AppCompatActivity{
 @Override protected void onCreate(Bundle b){super.onCreate(b);LinearLayout root=utils.screen(this,"Geospatial Change Detection","AI/ML-ready change analysis for validated satellite, drone or GIS feature inputs.");LinearLayout intro=utils.column(this);intro.addView(utils.text(this,"How it works",18,utils.TEXT,true));intro.addView(utils.text(this,"A production backend can compare time-series geospatial features and return a confidence-scored event. This offline prototype demonstrates the decision-support layer using synthetic metrics.",13,utils.MUTED,false));utils.addCard(root,intro,this);MaterialButton run=utils.button(this,"Run Change Analysis");root.addView(run);LinearLayout result=utils.column(this);root.addView(result);run.setOnClickListener(v->{ChangeDetectionManager.ChangeResult r=new ChangeDetectionManager().evaluate(12.0);result.removeAllViews();result.addView(utils.text(this,"Detected change: "+r.getChangePercentage()+"%",18,utils.TEXT,true));result.addView(utils.text(this,r.getDescription(),14,utils.MUTED,false));result.addView(utils.badge(this,r.isChanged()?"OFFICER REVIEW":"NO SIGNIFICANT CHANGE",!r.isChanged()));});utils.setScreenContentView(this, root);}
}
